:root {
  color-scheme: dark;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  background: #173b38;
  color: #f4edcf;
  --ink: #173b38;
  --paper: #f4edcf;
  --muted: #a9b7a2;
  --accent: #f0a24a;
  --line: #315a50;
}

* { box-sizing: border-box; }
body {
  min-width: 360px;
  min-height: 100vh;
  margin: 0;
  display: grid;
  place-items: center;
  padding: 24px 16px;
  background-color: #173b38;
  background-image: radial-gradient(#315a50 1px, transparent 1px);
  background-size: 18px 18px;
}
.board-shell {
  width: min(100%, 720px);
  padding: clamp(22px, 5vw, 40px);
  border: 4px solid #f4edcf;
  background: #204943;
  box-shadow: 9px 9px 0 #102d2a;
}
.board-header, .board-footer { display: flex; align-items: center; justify-content: space-between; gap: 20px; }
.eyebrow, .clock-label, .column-headings, .board-note {
  margin: 0;
  color: var(--muted);
  font-size: .78rem;
  font-weight: 800;
  letter-spacing: .12em;
}
h1 { margin: 8px 0 0; font-size: clamp(1.7rem, 6vw, 2.5rem); line-height: 1.1; }
.clock-panel { display: grid; gap: 4px; text-align: right; }
.clock { color: var(--accent); font-size: 2rem; font-weight: 850; font-variant-numeric: tabular-nums; }
.departures { margin-top: 32px; }
.column-headings, .train-row { display: grid; grid-template-columns: minmax(0, 1fr) 88px 100px; align-items: center; gap: 12px; }
.column-headings { padding: 0 14px 10px; font-size: .7rem; }
.column-headings span:nth-child(n+2) { text-align: right; }
.train-list { list-style: none; margin: 0; padding: 0; border-top: 2px solid var(--line); }
.train-row { min-height: 66px; padding: 10px 14px; border-bottom: 2px solid var(--line); background: #1b403b; }
.destination { min-width: 0; font-size: 1.05rem; font-weight: 750; }
.time, .platform { text-align: right; font-weight: 750; font-variant-numeric: tabular-nums; }
.platform { color: var(--muted); }
.train-row.next { position: relative; background: #f0a24a; color: var(--ink); }
.train-row.next::before { content: "▶"; position: absolute; left: -2px; top: 50%; transform: translate(-100%, -50%); color: var(--accent); font-size: .85rem; }
.train-row.next .platform { color: var(--ink); }
.train-row.departed { color: #81948b; background: #193832; }
.train-row.departed .platform { color: #71867d; }
.board-footer { margin-top: 24px; }
.status { margin: 0; color: var(--muted); font-weight: 650; }
button { min-height: 48px; padding: 10px 16px; border: 2px solid var(--paper); border-radius: 0; background: var(--paper); color: var(--ink); font: inherit; font-weight: 800; cursor: pointer; transition: transform 120ms ease, background 120ms ease, color 120ms ease; }
button span { margin-right: 5px; font-size: 1.2rem; vertical-align: -1px; }
button:hover { background: var(--accent); border-color: var(--accent); }
button:focus-visible { outline: 3px solid var(--accent); outline-offset: 4px; }
button:active { transform: translateY(3px); }
.board-note { margin: 24px 0 0; padding-top: 14px; border-top: 1px solid var(--line); text-align: center; font-size: .68rem; }
@media (max-width: 480px) {
  .board-shell { padding: 22px 16px; }
  .board-header, .board-footer { align-items: flex-start; flex-direction: column; }
  .clock-panel { text-align: left; }
  .departures { margin-top: 24px; }
  .column-headings, .train-row { grid-template-columns: minmax(0, 1fr) 62px 78px; gap: 8px; padding-right: 8px; padding-left: 8px; }
  .column-headings { font-size: .62rem; }
  .destination { font-size: .98rem; }
  .board-footer { gap: 14px; }
  button { width: 100%; }
}

const trains = [
  { destination: "Maplewood", time: "08:10", platform: "1" },
  { destination: "Riverside", time: "08:20", platform: "3" },
  { destination: "Pine Harbor", time: "08:35", platform: "2" },
  { destination: "Old Town", time: "08:50", platform: "4" },
  { destination: "Cedar Falls", time: "09:05", platform: "1" },
  { destination: "Lakeview", time: "09:20", platform: "3" }
];

let currentMinutes = 8 * 60;
const clock = document.querySelector("#clock");
const list = document.querySelector("#train-list");
const status = document.querySelector("#status");

function minutesOf(time) {
  const [hours, minutes] = time.split(":").map(Number);
  return hours * 60 + minutes;
}

function render() {
  const hours = Math.floor(currentMinutes / 60) % 24;
  const minutes = currentMinutes % 60;
  clock.textContent = `${String(hours).padStart(2, "0")}:${String(minutes).padStart(2, "0")}`;

  const nextIndex = trains.findIndex(train => minutesOf(train.time) > currentMinutes);
  list.replaceChildren(...trains.map((train, index) => {
    const row = document.createElement("li");
    const departed = minutesOf(train.time) <= currentMinutes;
    row.className = `train-row${departed ? " departed" : index === nextIndex ? " next" : ""}`;
    if (departed) row.setAttribute("aria-label", `${train.destination}, ${train.time}, platform ${train.platform}, departed`);
    else if (index === nextIndex) row.setAttribute("aria-label", `${train.destination}, ${train.time}, platform ${train.platform}, next departure`);

    const destination = document.createElement("span");
    destination.className = "destination";
    destination.textContent = train.destination;
    const time = document.createElement("span");
    time.className = "time";
    time.textContent = train.time;
    const platform = document.createElement("span");
    platform.className = "platform";
    platform.textContent = train.platform;
    row.append(destination, time, platform);
    return row;
  }));

  if (nextIndex === -1) status.textContent = "Service complete · all trains have departed";
  else {
    const remaining = minutesOf(trains[nextIndex].time) - currentMinutes;
    status.textContent = remaining === 0 ? "Departing now" : `Next departure in ${remaining} minute${remaining === 1 ? "" : "s"}`;
  }
}

document.querySelector("#advance-button").addEventListener("click", () => {
  currentMinutes = (currentMinutes + 5) % (24 * 60);
  render();
});

render();
